api.example:
const w = atelier.widget({
  id: "hello",
  title: "Hello",
  refresh: 60,
  view: () => atelier.ui.text(new Date().toLocaleTimeString(), { size: 22, weight: "bold" }),
});

atelier.paletteProvider({ id: "repos", title: "GitHub", prefix: "gh", search: async (q) =>
  (await myRepos()).filter((r) => r.name.includes(q)).map((r) => ({
    title: r.full_name, symbol: "book.closed", action: () => atelier.openURL(r.html_url) })) });

const a = atelier.liveActivity({ id: "upload", title: "Uploading", symbol: "arrow.up", progress: 0 });
a.update({ progress: 0.5 });
a.end();

const p = atelier.panel({ id: "stats", title: "Stats", width: 360, height: 240,
  html: "<h1>Hi</h1><script>atelier.onMessage((m) => document.body.append(m.text))</script>" });
atelier.command({ title: "Show Stats", run: () => { p.show(); p.post({ text: "Hello" }); } });
